const item = $input.first().json;
const password = String($env.AUTOBRR_IRC_WEBHOOK_PASSWORD || '');
if (!password) throw new Error('AUTOBRR_IRC_WEBHOOK_PASSWORD is not configured');
const auth = Buffer.from(String(item.headers?.authorization || ''));
const expected = Buffer.from('Basic ' + Buffer.from('grafana:' + password).toString('base64'));
let difference = auth.length ^ expected.length;
for (let i = 0; i < Math.max(auth.length, expected.length); i++) difference |= (auth[i] || 0) ^ (expected[i] || 0);
if (difference !== 0) throw new Error('Unauthorized Grafana webhook');
if (item.body?.status !== 'firing') return [];
const validName = /^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$/;
const networks = [...new Set((item.body?.alerts || []).filter(a => a.status === 'firing').map(a => String(a.labels?.network || '')).filter(n => validName.test(n)))];
if (!networks.length) throw new Error('Firing alert did not contain a valid network label');
return networks.map(network => ({ json: { network } }));
